<?php
declare(strict_types=1);require __DIR__.'/../../bootstrap.php';
if(!policy_flag('file_public_share',true)){http_response_code(503);exit('Public file sharing is temporarily disabled.');}
$token=preg_replace('/[^A-Za-z0-9_-]/','',(string)($_GET['token']??''));
$q=db()->prepare('SELECT s.*,l.id AS link_id,l.slug AS link_slug,l.clicks AS link_clicks FROM file_share_links s LEFT JOIN short_links l ON l.id=s.link_id WHERE s.token=?');$q->execute([$token]);$share=$q->fetch();
if(!$share){http_response_code(404);exit('Share not found.');}
if(!empty($share['revoked_at'])){http_response_code(410);exit('This share has been revoked.');}
if(!empty($share['expires_at'])&&strtotime($share['expires_at'])<=time()){http_response_code(410);exit('This share has expired.');}
if((int)$share['max_downloads']>0&&(int)$share['downloads']>=(int)$share['max_downloads']){http_response_code(410);exit('This share download limit has been reached.');}
$canZip=policy_allows((int)$share['user_id'],'file_zip_downloads',false);
$unlocked=true;if(!empty($share['password_hash'])){if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$unlocked=password_verify((string)($_POST['password']??''),(string)$share['password_hash']);if($unlocked)$_SESSION['file_share_unlock_'.$share['id']]=time();}else $unlocked=((int)($_SESSION['file_share_unlock_'.$share['id']]??0)>time()-900)||(!empty($share['link_id'])&&(int)($_SESSION['link_unlock_'.$share['link_id']]??0)>time()-900);if(!$unlocked){?><!doctype html><html><meta name="viewport" content="width=device-width,initial-scale=1"><body style="font-family:system-ui;background:#f6f8fc;display:grid;place-items:center;min-height:100vh"><form method="post" style="background:#fff;padding:28px;border-radius:18px;box-shadow:0 12px 40px #0001;width:min(420px,90%)"><?php echo csrf_field();?><h2>Password protected share</h2><p>This link is protected. Enter the password to continue.</p><input name="password" type="password" required autofocus style="width:100%;box-sizing:border-box;padding:12px;border:1px solid #d8deea;border-radius:10px"><button style="margin-top:12px;width:100%;padding:12px;border:0;border-radius:10px;background:#2563eb;color:#fff;font-weight:700">Unlock</button></form></body></html><?php exit;}}
$q=db()->prepare('SELECT f.* FROM file_share_items i JOIN file_objects f ON f.id=i.file_id WHERE i.share_id=? AND f.status=\'clean\' AND f.trashed_at IS NULL ORDER BY i.sort_order,i.file_id');$q->execute([(int)$share['id']]);$files=$q->fetchAll();
file_record_share_event((int)$share['id'],'view');
$theme=json_decode((string)($share['theme_json']??''),true);$theme=is_array($theme)?$theme:[];$accent=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($theme['accent']??''))?$theme['accent']:'#2563eb';$background=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($theme['background']??''))?$theme['background']:'#f6f8fc';$cardColor=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($theme['card']??''))?$theme['card']:'#fff';
$shortUrl=!empty($share['link_slug'])?link_public_url((string)$share['link_slug']):file_share_url($token);$qrHref=!empty($share['link_slug'])?'/qr/'.rawurlencode((string)$share['link_slug']):'';$ogTitle=(string)($share['og_title']?:$share['title']);$ogDescription=(string)($share['og_description']?:'Secure file sharing from PocketCat.');$ogImage=(string)($share['og_image_url']??'');
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="<?=e($ogDescription)?>"><meta property="og:title" content="<?=e($ogTitle)?>"><meta property="og:description" content="<?=e($ogDescription)?>"><meta property="og:url" content="<?=e($shortUrl)?>"><?php if($ogImage):?><meta property="og:image" content="<?=e($ogImage)?>"><?php endif;?><meta name="twitter:card" content="summary_large_image"><title><?=e($share['title'])?> — PocketCat</title><style>:root{--accent:<?=$accent?>;--bg:<?=$background?>;--card:<?=$cardColor?>}*{box-sizing:border-box}body{font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif;background:var(--bg);color:#172033;margin:0}.wrap{max-width:1080px;margin:28px auto;padding:16px}.hero{background:linear-gradient(135deg,color-mix(in srgb,var(--accent) 12%,#fff),var(--card));border:1px solid #e3e8f1;border-radius:24px;padding:26px;box-shadow:0 16px 45px #0000000b}.eyebrow{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--accent);font-weight:800}.muted{color:#68758a}.share-url{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:14px 0}.share-url input{flex:1;min-width:220px;padding:11px;border:1px solid #d9e0ea;border-radius:10px;background:#fff}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;padding:10px 14px;border-radius:11px;background:var(--accent);color:#fff;text-decoration:none;font-weight:750;border:0;cursor:pointer}.btn.secondary{background:#eef2f7;color:#26354b}.btn.social{background:#fff;color:#243149;border:1px solid #dfe5ed}.items{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:16px;margin-top:18px}.item{background:var(--card);border:1px solid #e4e8f0;border-radius:18px;padding:16px;box-shadow:0 8px 28px #00000008}.preview{max-width:100%;max-height:52vh;display:block;margin:12px auto;border-radius:12px;background:#f2f5f9}.shared-image-wrap{position:relative}.shared-image-wrap:fullscreen{background:#080b12;display:grid;place-items:center;padding:24px}.shared-image-wrap:fullscreen .shared-image{max-width:96vw;max-height:90vh;object-fit:contain}.shared-image-fullscreen{display:block;margin:0 auto 8px}video,audio{width:100%}iframe{width:100%;height:55vh;border:0;border-radius:12px}pre{overflow:auto;max-height:55vh;background:#111827;color:#e5e7eb;padding:16px;border-radius:12px}.file-actions{margin-top:12px}.bulk-tools{position:sticky;top:10px;z-index:20;margin:18px 0;padding:14px;border:1px solid #d9e2f0;border-radius:16px;background:color-mix(in srgb,var(--card) 92%,transparent);box-shadow:0 8px 28px #17203312;display:flex;gap:9px;align-items:center;flex-wrap:wrap}.bulk-tools[hidden]{display:none}.bulk-tools select{padding:10px;border:1px solid #d9e0ea;border-radius:10px;max-width:100%}.item-select{display:flex;align-items:center;gap:8px;margin-bottom:8px;font-weight:700}.item-select input{width:18px;height:18px;accent-color:var(--accent)}.notice{margin-top:12px;padding:10px 12px;border-radius:10px;background:#f7f9fc}.topline{display:flex;justify-content:space-between;gap:10px;align-items:flex-start;flex-wrap:wrap}@media(max-width:640px){.wrap{margin:8px auto;padding:10px}.hero{padding:18px}.items{grid-template-columns:1fr}.share-url input{min-width:100%}}</style><link rel="stylesheet" href="/assets/css/universal-media-viewer-v18.css?v=18.8"></head><body><div class="wrap"><section class="hero"><div class="topline"><div><span class="eyebrow">PocketCat File Share</span><h1 style="margin:6px 0 8px"><?=e($share['title'])?></h1><p class="muted" style="margin:0"><?=count($files)?> file(s)<?php if($share['expires_at']):?> · Expires <?=e($share['expires_at'])?><?php endif;?><?php if((int)$share['view_only']===1):?> · View only<?php endif;?><?php if((int)$share['max_downloads']>0):?> · <?=max(0,(int)$share['max_downloads']-(int)$share['downloads'])?> downloads remaining<?php endif;?></p></div><?php if($qrHref!==''):?><?php endif;?></div><div class="share-url"><input id="shareUrl" readonly value="<?=e($shortUrl)?>"><button class="btn" id="copyBtn">Copy Link</button><button class="btn" id="nativeBtn">Device Share</button></div><div class="actions"><button class="btn social" data-social="whatsapp">WhatsApp</button><button class="btn social" data-social="facebook">Facebook</button><button class="btn social" data-social="instagram">Instagram</button><?php if((int)$share['view_only']===0):?><button class="btn secondary" id="selectAllItemsStart" type="button">Select all files</button><button class="btn" id="zip">Download all as ZIP</button><?php else:?><span class="notice muted">View-only sharing is enabled; downloads are disabled.</span><?php endif;?></div></section><?php if((int)$share['view_only']===0):?><div class="bulk-tools" id="bulkTools" hidden><strong id="selectedCount">0 items selected</strong><button class="btn secondary" type="button" id="selectAllItems">Select all</button><button class="btn secondary" type="button" id="clearItems">Deselect all</button><select id="bulkMode" aria-label="Download mode"><option value="original">Original files</option><option value="single">One archive</option><option value="separate">Separate archives (bundled)</option></select><select id="archiveFormat" aria-label="Archive format"><option value="zip">.zip</option><option value="tar">.tar</option><option value="tar.gz">.tar.gz</option><option value="tar.bz2">.tar.bz2</option><option value="7z">.7z</option><option value="rar">.rar</option><option value="tar.xz">.tar.xz</option><option value="gz">.gz</option><option value="bz2">.bz2</option><option value="xz">.xz</option></select><button class="btn" type="button" id="bulkDownload">Download selected</button><span class="muted" id="bulkStatus" role="status"></span></div><?php endif;?><div class="items"><?php foreach($files as $f):$itemKey=hash_hmac('sha256',(string)$f['id'],$token);$asset='/file/share/asset.php?token='.rawurlencode($token).'&item='.$itemKey;?><article class="item" data-file-id="<?=e((string)$f['id'])?>"><?php if((int)$share['view_only']===0):?><label class="item-select"><input type="checkbox" class="share-item-check" value="<?=e((string)$f['id'])?>" aria-label="Select <?=e($f['original_name'])?>"> Select file</label><?php endif;?><strong><?=e($f['relative_path']?:$f['original_name'])?></strong><div class="muted"><?=e($f['mime_type'])?> · <?=e(storage_human((int)$f['size_bytes']))?> · Uploaded <?=e(date('M j, Y',strtotime((string)$f['created_at'])))?> · <?=number_format((int)$f['downloads'])?> downloads</div><?php if(str_starts_with($f['mime_type'],'image/')):?><div class="shared-image-wrap"><img class="preview shared-image" src="<?=e($asset)?>" alt="<?=e($f['original_name'])?>"><button class="btn secondary shared-image-fullscreen" type="button" aria-label="View image full screen">⛶ Full screen</button></div><?php elseif(str_starts_with($f['mime_type'],'video/')):?><video class="preview" controls preload="metadata" src="<?=e($asset)?>"></video><?php elseif(str_starts_with($f['mime_type'],'audio/')):?><audio controls preload="metadata" src="<?=e($asset)?>"></audio><?php elseif($f['mime_type']==='application/pdf'):?><iframe src="<?=e($asset)?>" loading="lazy"></iframe><?php elseif(str_starts_with($f['mime_type'],'text/')):?><pre class="text-preview" data-preview-url="<?=e($asset . '&mode=text')?>">Loading text preview…</pre><?php else:?><div class="notice muted">Preview is not available for this file type. Download the original file instead.</div><?php endif;?><div class="actions file-actions"><?php if(str_starts_with($f['mime_type'],'image/')||str_starts_with($f['mime_type'],'video/')||str_starts_with($f['mime_type'],'audio/')):?><button class="btn secondary" type="button" data-public-preview data-url="<?=e($asset)?>" data-download="<?=((int)$share['view_only']===0)?e($asset . '&mode=download'):''?>" data-name="<?=e($f['original_name'])?>" data-mime="<?=e($f['mime_type'])?>">Preview</button><?php endif;?><?php if((int)$share['view_only']===0):?><button class="btn download-file" data-item-url="<?=e($asset . '&mode=download')?>">Download</button><?php endif;?></div></article><?php endforeach;?></div></div><script>const SHARE_TOKEN=<?=json_encode($token)?>,SHORT_URL=<?=json_encode($shortUrl)?>,CSRF=<?=json_encode((string)($_SESSION['_csrf']??''))?>;function pcConfirm(title,message,yes='Continue'){return new Promise(resolve=>{let h=document.getElementById('pcShareConfirm');if(!h){h=document.createElement('div');h.id='pcShareConfirm';h.style.cssText='position:fixed;inset:0;z-index:10000;background:#07111dcc;display:grid;place-items:center;padding:18px';h.innerHTML='<section role="dialog" aria-modal="true" style="width:min(100%,440px);background:#fff;color:#172033;border-radius:18px;padding:24px;box-shadow:0 24px 70px #0004"><h2 data-title></h2><p data-message style="white-space:pre-line"></p><div style="display:flex;justify-content:flex-end;gap:10px"><button type="button" data-no class="btn secondary">Cancel</button><button type="button" data-yes class="btn"></button></div></section>';document.body.appendChild(h)}h.querySelector('[data-title]').textContent=title;h.querySelector('[data-message]').textContent=message;h.querySelector('[data-yes]').textContent=yes;h.hidden=false;const finish=v=>{h.hidden=true;resolve(v)};h.querySelector('[data-no]').onclick=()=>finish(false);h.querySelector('[data-yes]').onclick=()=>finish(true);h.onclick=e=>{if(e.target===h)finish(false)};h.querySelector('[data-yes]').focus()})}document.querySelectorAll('.shared-image-fullscreen').forEach(b=>b.onclick=async()=>{const box=b.closest('.shared-image-wrap');try{if(!document.fullscreenElement)await box.requestFullscreen();else await document.exitFullscreen()}catch(e){}});const copy=async()=>{try{await navigator.clipboard.writeText(SHORT_URL);document.getElementById('copyBtn').textContent='Copied!';setTimeout(()=>document.getElementById('copyBtn').textContent='Copy Link',1400)}catch(e){const x=document.getElementById('shareUrl');x.select();document.execCommand('copy')}};document.getElementById('copyBtn').onclick=copy;document.getElementById('nativeBtn').onclick=()=>navigator.share?navigator.share({title:document.title,url:SHORT_URL}).catch(()=>{}):copy();document.querySelectorAll('[data-social]').forEach(b=>b.onclick=()=>{const s=b.dataset.social,u=encodeURIComponent(SHORT_URL);if(s==='whatsapp')open('https://wa.me/?text='+u,'_blank');else if(s==='facebook')open('https://www.facebook.com/sharer/sharer.php?u='+u,'_blank');else{copy();open('https://www.instagram.com/','_blank')}});document.querySelectorAll('.text-preview').forEach(x=>fetch(x.dataset.previewUrl,{credentials:'same-origin',headers:{'Accept':'application/json'}}).then(r=>r.json()).then(j=>{if(j.content!==undefined)x.textContent=j.content;else throw Error('Preview unavailable')}).catch(()=>x.textContent='Preview unavailable.'));document.querySelectorAll('.download-file').forEach(b=>b.onclick=()=>{b.disabled=true;location.href=b.dataset.itemUrl;setTimeout(()=>b.disabled=false,1800)});const checks=[...document.querySelectorAll('.share-item-check')],tools=document.getElementById('bulkTools'),countEl=document.getElementById('selectedCount'),statusEl=document.getElementById('bulkStatus');function selectedIds(){return checks.filter(c=>c.checked).map(c=>Number(c.value));}function syncSelection(){const ids=selectedIds();if(tools)tools.hidden=!ids.length;if(countEl)countEl.textContent=ids.length+' item'+(ids.length===1?'':'s')+' selected';const all=document.getElementById('selectAllItems');if(all)all.textContent=checks.length&&ids.length===checks.length?'All selected':'Select all';}checks.forEach(c=>c.addEventListener('change',syncSelection));document.getElementById('selectAllItems')?.addEventListener('click',()=>{checks.forEach(c=>c.checked=true);syncSelection()});document.getElementById('selectAllItemsStart')?.addEventListener('click',()=>{checks.forEach(c=>c.checked=true);syncSelection();document.getElementById('bulkTools')?.scrollIntoView({behavior:'smooth',block:'nearest'});});document.getElementById('clearItems')?.addEventListener('click',()=>{checks.forEach(c=>c.checked=false);syncSelection()});async function downloadBlobResponse(response,fallback){if(!response.ok){const j=await response.json().catch(()=>({}));throw Error(j.error||fallback)}const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=response.headers.get('Content-Disposition')?.match(/filename="?([^";]+)"?/i)?.[1]||fallback;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}document.getElementById('bulkDownload')?.addEventListener('click',async()=>{const ids=selectedIds();if(!ids.length)return;const mode=document.getElementById('bulkMode').value,format=document.getElementById('archiveFormat').value;if(mode==='original'){if(!await pcConfirm('Download original files?','Download '+ids.length+' original file(s) individually? Your browser may ask permission for multiple downloads.','Download'))return;const selected=new Set(ids.map(String));const links=[...document.querySelectorAll('.download-file')].filter(b=>selected.has(b.closest('.item')?.dataset.fileId)).map(b=>b.dataset.itemUrl);for(let i=0;i<links.length;i++){const a=document.createElement('a');a.href=links[i];a.download='';a.rel='noopener';document.body.appendChild(a);a.click();a.remove();await new Promise(resolve=>setTimeout(resolve,350));}return;}if(statusEl)statusEl.textContent='Preparing archive… the browser will stream the download directly.';const b=document.getElementById('bulkDownload');b.disabled=true;try{const form=document.createElement('form');form.method='POST';form.action='/api/files/?action=zip';form.target='_blank';form.hidden=true;const add=(name,value)=>{const x=document.createElement('input');x.type='hidden';x.name=name;x.value=String(value);form.appendChild(x)};add('_csrf',CSRF);add('share_token',SHARE_TOKEN);add('mode',mode);add('format',format);ids.forEach(id=>add('ids[]',id));document.body.appendChild(form);form.submit();form.remove();if(statusEl)statusEl.textContent='Archive request submitted. The server is preparing a streamed download.';}catch(e){if(statusEl)statusEl.textContent=e.message||'Download failed.';}finally{b.disabled=false;}});document.getElementById('zip')?.addEventListener('click',()=>{document.querySelectorAll('.share-item-check').forEach(c=>c.checked=true);syncSelection();document.getElementById('bulkMode').value='single';document.getElementById('archiveFormat').value='zip';document.getElementById('bulkDownload')?.click()});</script><script src="/assets/js/universal-media-viewer-v18.js?v=18.8" defer></script></body></html>
<?php if(!$canZip): ?><script>document.getElementById('zip')?.remove();document.getElementById('bulkTools')?.remove();</script><?php endif; ?>